catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    //Type appropriate comment here, and begin script below
    var slt_start_date = g_form.getValue('event_start_date');
    var slt_end_date = g_form.getValue('event_end_date');
    var selected_room = g_form.getValue('room_location');
    //alert(slt_start_date);
    //alert(slt_end_date);
	g_form.setReadOnly('requested_room', true);
    g_form.clearValue('requested_room', true);
    if ((slt_start_date != "" || slt_end_date != "") && (selected_room == 'Conference Center')) {
       // g_form.setMandatory('requested_room', true);

    }
    if ((slt_start_date == "") && (selected_room == 'Conference Center')) {
        g_form.setReadOnly('requested_room', true);
      //  g_form.setMandatory('requested_room', true);

    }
    if ((slt_end_date == "") && (selected_room == 'Conference Center')) {
        g_form.setReadOnly('requested_room', true);
        g_form.setMandatory('requested_room', true);

    }
}
